{
  "spec_version": 1.0,
  "title": "Tính khoảng cách từ đỉnh C đến mặt phẳng (SBD)",
  "description": "Bài toán này minh họa cách tính khoảng cách từ một điểm đến một mặt phẳng trong không gian bằng cách dựng hình và sử dụng phép đo khoảng cách.",
  "memory_declarations": [
    {
      "name": "SBD",
      "type": "plane3"
    },
    {
      "name": "khoang_cach_c_sbd",
      "type": "float"
    }
  ],
  "statements": [
    {
      "kind": "declare_point",
      "target_var": "A",
      "at": [0, 0, 0],
      "model_assumption": "chọn A làm gốc toạ độ"
    },
    {
      "kind": "declare_point",
      "target_var": "B",
      "at": [6, 0, 0],
      "source_fact_id": "ab_length",
      "model_assumption": "chọn cạnh AB nằm trên trục Ox"
    },
    {
      "kind": "declare_point",
      "target_var": "D",
      "at": [0, 4, 0],
      "source_fact_id": "ad_length",
      "model_assumption": "chọn cạnh AD nằm trên trục Oy do AB vuông góc với AD"
    },
    {
      "kind": "declare_point",
      "target_var": "S",
      "at": [0, 0, 3],
      "source_fact_id": "sa_length",
      "model_assumption": "chọn SA nằm trên trục Oz do SA vuông góc với mặt phẳng (ABCD) tại A"
    },
    {
      "kind": "assign",
      "target_var": "vec_AD",
      "expr": {
        "kind": "vector_from_points",
        "from_point": "A",
        "to_point": "D"
      }
    },
    {
      "kind": "construct_point",
      "target_var": "C",
      "expr": {
        "kind": "translate",
        "point": "B",
        "vector": "vec_AD"
      },
      "source_fact_id": "abcd_hinh_binh_hanh",
      "label": "Đỉnh C của hình bình hành ABCD"
    },
    {
      "kind": "construct_plane",
      "target_var": "SBD",
      "through": ["S", "B", "D"],
      "label": "Mặt phẳng (SBD)"
    },
    {
      "kind": "assign",
      "target_var": "khoang_cach_c_sbd",
      "expr": {
        "kind": "measure",
        "quantity": "distance",
        "of": "C",
        "wrt": "SBD"
      }
    }
  ],
  "pedagogical_intent": "Học sinh sẽ thấy cách thiết lập hệ toạ độ phù hợp để đơn giản hóa việc dựng hình và tính toán các đối tượng hình học."
}

{
  "spec_version": 1.0,
  "title": "Tính khoảng cách từ đỉnh B' đến mặt phẳng (A'BC)",
  "description": "Dựng lăng trụ đứng ABC.A'B'C' có đáy ABC vuông tại A, sau đó tính khoảng cách từ đỉnh B' đến mặt phẳng (A'BC).",
  "memory_declarations": [
    {
      "name": "A_prime_BC",
      "type": "plane3",
      "model_assumption": "Mặt phẳng (A'BC) được tạo bởi ba điểm A', B, C"
    },
    {
      "name": "khoang_cach_b_prime_a_prime_bc",
      "type": "float",
      "model_assumption": "Khoảng cách từ B' đến mặt phẳng (A'BC)"
    }
  ],
  "statements": [
    {
      "kind": "declare_point",
      "target_var": "A",
      "at": [0, 0, 0],
      "model_assumption": "Chọn A làm gốc toạ độ"
    },
    {
      "kind": "declare_point",
      "target_var": "B",
      "at": [2, 0, 0],
      "source_fact_id": "ab_length",
      "model_assumption": "AB nằm trên trục Ox"
    },
    {
      "kind": "declare_point",
      "target_var": "C",
      "at": [0, 6, 0],
      "source_fact_id": "ac_length",
      "model_assumption": "AC nằm trên trục Oy, đáy ABC vuông tại A"
    },
    {
      "kind": "declare_point",
      "target_var": "A_prime",
      "at": [0, 0, 3],
      "source_fact_id": "aa_prime_length",
      "model_assumption": "AA' vuông góc với đáy và nằm trên trục Oz"
    },
    {
      "kind": "declare_point",
      "target_var": "B_prime",
      "at": [2, 0, 3],
      "model_assumption": "B' là đỉnh của lăng trụ đứng, được xác định từ B và AA'"
    },
    {
      "kind": "construct_plane",
      "target_var": "A_prime_BC",
      "through": ["A_prime", "B", "C"],
      "label": "Mặt phẳng (A'BC)"
    },
    {
      "kind": "assign",
      "target_var": "khoang_cach_b_prime_a_prime_bc",
      "expr": {
        "kind": "measure",
        "quantity": "distance",
        "of": "B_prime",
        "wrt": "A_prime_BC"
      }
    }
  ],
  "pedagogical_intent": "Bài toán này minh họa cách thiết lập hệ tọa độ cho lăng trụ đứng và tính khoảng cách từ một điểm đến một mặt phẳng."
}

