      "label": "Đỉnh A'"
    },
    {
      "kind": "construct_point",
      "target_var": "C",
      "expr": {
        "kind": "translate",
        "point": "B",
        "vector": {
          "kind": "vector_from_points",
          "from_point": "A",
          "to_point": "D"
        }
      },
      "label": "Đỉnh C"
    },
    {
      "kind": "construct_point",
      "target_var": "B_prime",
      "expr": {
        "kind": "translate",
        "point": "B",
        "vector": {
          "kind": "vector_from_points",
          "from_point": "A",
          "to_point": "A_prime"
        }
      },
      "label": "Đỉnh B'"
    },
    {
      "kind": "construct_point",
      "target_var": "C_prime",
      "expr": {
        "kind": "translate",
        "point": "C",
        "vector": {
          "kind": "vector_from_points",
          "from_point": "A",
          "to_point": "A_prime"
        }
      },
      "label": "Đỉnh C'"
    },
    {
      "kind": "construct_point",
      "target_var": "D_prime",
      "expr": {
        "kind": "translate",
        "point": "D",
        "vector": {
          "kind": "vector_from_points",
          "from_point": "A",
          "to_point": "A_prime"
        }
      },
      "label": "Đỉnh D'"
    },
    {
      "kind": "construct_point",
      "target_var": "M",
      "expr": {
        "kind": "midpoint",
        "a": "C",
        "b": "C_prime"
      },
      "source_fact_id": "m_midpoint_cc_prime",
      "label": "Trung điểm M của CC'"
    },
    {
      "kind": "construct_line",
      "target_var": "B'M",
      "through_a": "B_prime",
      "through_b": "M",
      "label": "Đường thẳng B'M"
    },
    {
      "kind": "assign",
      "target_var": "khoang_cach_a_b_prime_m",
      "expr": {
        "kind": "measure",
        "quantity": "distance",
        "of": "A",
        "wrt": "B'M"
      }
    }
  ],
  "pedagogical_intent": "Chương trình này minh họa cách dựng hình hộp chữ nhật và các điểm liên quan, sau đó tính khoảng cách từ một điểm đến một đường thẳng trong không gian."
}

