    {
      "kind": "construct_line",
      "target_var": "AC_line",
      "through_a": "A",
      "through_b": "C",
      "label": "Đường chéo AC"
    },
    {
      "kind": "construct_line",
      "target_var": "BD_line",
      "through_a": "B",
      "through_b": "D",
      "label": "Đường chéo BD"
